  amrex::Real x8 = sc[12] + 3.0 * sc[13] + 3.0 * sc[14] + sc[16] + sc[17] +
                   sc[18] + sc[19] + sc[1] + sc[20] + sc[2] + sc[4] + sc[6] +
                   sc[7] + sc[8];
  amrex::Real x9 = 3.0 * sc[15] + 2 * sc[9];
  amrex::Real x12 = 2 * sc[0] + 1.5 * sc[10] + 6.0 * sc[5];
